#include <bitset>
#include <iostream>

int main() {
    std::bitset<8> b1(0b11001100);
    std::bitset<8> b2(0b10101010);

    // Non-mutating AND operation
    std::bitset<8> b_and = b1 & b2; 

    // Non-mutating complement
    std::bitset<8> b_not = ~b1;

    // Non-mutating left shift
    std::bitset<8> b_shift = b1 << 2;

    // Check immutability (b1 remains 11001100)
    // std::cout << b1.to_string() << std::endl; 
    // std::cout << b_and.to_string() << std::endl; // 10001000

    // Contrast with Mutating operation:
    // b1 &= b2; // b1 would be modified here
}
